coding.prompt:
Write a class `OrderBuilder` with defaults `{ customer: 'guest', items: [], currency: 'GBP' }`. Methods `forCustomer(name)`, `withItem(sku, qty)` (appends `{ sku, qty }`) and `inCurrency(code)` each return `this`. `build()` returns a **new** plain object each call, so mutating one built order never affects another.

```js
new OrderBuilder().withItem('A1', 2).build()
// { customer: 'guest', items: [{ sku: 'A1', qty: 2 }], currency: 'GBP' }
```

coding.starter:
class OrderBuilder {
  // add constructor, fluent methods and build()
}

coding.solution:
class OrderBuilder {
  constructor() {
    this.customer = 'guest';
    this.items = [];
    this.currency = 'GBP';
  }
  forCustomer(name) { this.customer = name; return this; }
  withItem(sku, qty) { this.items.push({ sku, qty }); return this; }
  inCurrency(code) { this.currency = code; return this; }
  build() {
    return { customer: this.customer, items: this.items.map(i => ({ ...i })), currency: this.currency };
  }
}

function driverConfig(env) {
  const configs = {
    local: { browser: 'chrome', headless: false, remoteUrl: null },
    ci: { browser: 'chrome', headless: true, remoteUrl: null },
    grid: { browser: 'firefox', headless: true, remoteUrl: 'http://grid:4444' },
  };
  if (!Object.prototype.hasOwnProperty.call(configs, env)) {
    throw new Error('unknown environment');
  }
  return { ...configs[env] };
}
